from collections import deque
def components(mask):
    cells=set(mask); comps=[]
    while cells:
        s=cells.pop(); q=[s]; comp={s}
        while q:
            r,c=q.pop()
            for t in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                if t in cells: cells.remove(t);comp.add(t);q.append(t)
        comps.append(comp)
    return sorted([len(x) for x in comps],reverse=True)
