def walkpath(t,start=(0,0)):
 prev=None; cur=start; seq=[cur]
 while True:
  opts=[(cur[0]+dr,cur[1]+dc) for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)] if (cur[0]+dr,cur[1]+dc) in t and (cur[0]+dr,cur[1]+dc)!=prev]
  if not opts: break
  nxt=opts[0];prev,cur=cur,nxt;seq.append(cur)
 return seq
